// Java implementation of the "forceDeleteOnExit" method
public class ForceDeleteOnExitImpl implements ForceDeleteOnExit {
    // Method implementation
    public void forceDeleteOnExit(File file) throws IOException {
        // Check if the file is a directory and delete it recursively
        if (file.isDirectory()) {
            deleteDirectory(file);
        } else {
            // Delete the file
            if (!file.delete()) {
                throw new IOException("Failed to delete file: " + file);
            }
        }
    }

    // Recursive method to delete a directory and all its sub-directories
    private static void deleteDirectory(File dir) throws IOException {
        // Check if the directory exists
        if (dir.exists()) {
            // Read all the files in the directory
            String[] files = dir.list();
            if (files != null) {
                for (String file : files) {
                    File currentFile = new File(dir, file);
                    // Check if the file is a directory and delete it recursively
                    if (currentFile.isDirectory()) {
                        deleteDirectory(currentFile);
                    } else {
                        // Delete the file
                        if (!currentFile.delete()) {
                            throw new IOException("Failed to delete file: " + currentFile);
                        }
                    }
                }
            }
            // Delete the directory
            if (!dir.delete()) {
                throw new IOException("Failed to delete directory: " + dir);
            }
        }
    }
}

