 public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
     // Initialize a new bipartite graph
     BiPartiteGraph<V, E> bipartiteGraph = new BiPartiteGraph<V, E>();

     // Add all vertices of the graph to the bipartite graph
     for (V vertex : target.getVertices()) {
         bipartiteGraph.addVertex(vertex);
     }

     // Add all edges of the graph to the bipartite graph
     for (E edge : target.getEdges()) {
         V source = edge.getSource();
         V target = edge.getTarget();
         if (resultMap.containsKey(source) && resultMap.containsKey(target)) {
             bipartiteGraph.addEdge(source, target);
         }
     }

     // Return the bipartite graph
     return bipartiteGraph;
 }

/**
 * Construct a complete bipartite graph
 */
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Create a new graph with the same number of vertices as the number of elements in the result map
    Graph<V, E> graph = Graphs.copyOf(target, resultMap.size());

    // Add a new vertex to the graph for each element in the result map
    Set<V> vertices = new HashSet<>(resultMap.values());
    for (V vertex : vertices) {
        graph.addVertex(vertex);
    }

    // Add a new edge to the graph for each pair of elements in the result map
    for (V element1 : vertices) {
        for (V element2 : vertices) {
            if (element1 != element2) {
                graph.addEdge(element1, element2);
            }
        }
    }

    // Return the constructed graph
    return graph;
}

