public static void writeDelimitedTo(OutputStream out, ByteBuffer message, Schema<T> schema, LinkedBuffer buffer) throws IOException {

 // calculate the size of the message
 int messageSize = schema.sizeof(message);

 // write the message size to the output stream
 out.write(messageSize);

 // write the message to the output stream
 buffer.wrap(message);
 schema.writeTo(buffer, out);

 // reset the buffer
 buffer.clear();

 return messageSize;
}

/**
 * Serializes the {@code message}, prefixed with its length, into an {@link OutputStream}.
 *
 * @param out       the output stream to write to
 * @param message   the message to serialize
 * @param schema    the schema of the message
 * @param buffer    the buffer to use for serialization
 * @return the size of the message
 * @throws IOException if an I/O error occurs
 */
public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    out.write(new byte[] { (byte) (size & 0xFF), (byte) ((size >> 8) & 0xFF), (byte) ((size >> 16) & 0xFF), (byte) ((size >> 24) & 0xFF) });
    schema.writeTo(out, message, buffer);
    return size;
}

public static int writeDelimitedTo(OutputStream out, Object message, Schema schema, LinkedBuffer buffer) throws IOException {
return new DelimitedIo.Writer(out, message, schema, buffer).write().size;
}

