import org.elasticsearch.index.mapper.Mappings;

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Get the current index mappings from the Elasticsearch cluster
    Mappings currentMappings = getCurrentMappings(tableName);

    // Create a new map to store the fields that exist in the input mappings but not in the current mappings
    Map<String, Map<String, Object>> newMappings = new HashMap<>();

    // Iterate over the fields in the input mappings
    for (String field : mappings.fieldMappings().keySet()) {
        // If the field does not exist in the current mappings, add it to the new mappings
        if (!currentMappings.fieldMappings().keySet().contains(field)) {
            newMappings.put(field, mappings.fieldMappings().get(field));
        }
    }

    // Return the new mappings
    return new Mappings(newMappings);
}

// Get the current mappings from the Elasticsearch cluster
private Mappings getCurrentMappings(String tableName) {
    // Create a new client to connect to the Elasticsearch cluster
    TransportClient client = new PreBuiltTransportClient(Settings.EMPTY);

    // Connect to the Elasticsearch cluster
    client.addTransportAddress(new InetSocketTransportAddress(InetAddress.getByName("localhost"), 9300));

    // Get the current mappings from the index
    IndicesAdminClient indicesClient = client.admin().indices();
    GetIndexResponse indexResponse = indicesClient.prepareGetIndex().setIndices(tableName).setTypes("_all").execute().actionGet();

    // Create a new mappings object from the current mappings
    Mappings mappings = Mappings.fromXContent(XContentFactory.jsonBuilder().copyCurrentStructure(indexResponse.getMappings().get(tableName)));

    // Close the client
    client.close();

    // Return the current mappings
    return mappings;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    return mappings.getMappings().entrySet().stream()
            .filter(entry -> !entry.getValue().containsKey(tableName))
            .map(entry -> entry.getValue())
            .collect(Collectors.toMap(
                    Map.Entry::getKey,
                    Map.Entry::getValue
            ));
}

