public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the day number from the time bucket
    int dayNumber = (int) (timeBucket / dayStep);

    // Calculate the day number offset from the current day number
    int dayNumberOffset = dayNumber % dayStep;

    // Calculate the re-formatted time bucket
    long reFormattedTimeBucket = timeBucket - dayNumberOffset;

