    long timeBucketYear = timeBucket / 100000000;
    long timeBucketMonth = (timeBucket % 100000000) / 10000;
    long timeBucketDay = (timeBucket % 10000) / 100;
    long timeBucketHour = (timeBucket % 100) / 1;
    long timeBucketMinute = (timeBucket % 1) * 60;
    long timeBucketSecond = 0;
    for (int i = 0; i < dayStep; i++) {
        timeBucketSecond = timeBucketSecond + 86400;
    }
    return timeBucketYear * 100000000 + timeBucketMonth * 10000 + timeBucketDay * 100 + timeBucketHour * 1 + timeBucketMinute * 60 + timeBucketSecond;
}

