/**
 * Compute all vertices that have positive degree by iterating over the edges on purpose. This keeps the complexity to $O(m)$ where $m$ is the number of edges.
 *
 * @return set of vertices with positive degree
 */
private Set<V> initVisibleVertices() {
    Set<V> visibleVertices = new HashSet<>();

    // Iterate over all edges in the graph
    Iterator<E> edgeIterator = graph.edgeIterator();
    while (edgeIterator.hasNext()) {
        E edge = edgeIterator.next();

        // Add the destination vertex of the edge to the set of visible vertices
        // if its degree is positive
        V vertex = graph.getDestination(edge);
        if (vertex.getDegree() > 0) {
            visibleVertices.add(vertex);
        }
    }

    return visibleVertices;
}

