public static String trimTrailingWhitespace(String str) {
    // Find the last non-whitespace character
    int lastNonWhitespaceIdx = str.length() - 1;
    for (int i = lastNonWhitespaceIdx; i >= 0; i--) {
        char c = str.charAt(i);
        if (!Character.isWhitespace(c)) {
            lastNonWhitespaceIdx = i;
            break;
        }
    }

    // Trim the String to the last non-whitespace character
    if (lastNonWhitespaceIdx == str.length() - 1 || lastNonWhitespaceIdx == -1) {
        return str;
    }
    return str.substring(0, lastNonWhitespaceIdx + 1);
}

public static String trimTrailingWhitespace(String str) {
    int strLen = str.length();
    if (strLen > 0 && Character.isWhitespace(str.charAt(strLen - 1))) {
        int newStrLen = strLen;
        while (newStrLen > 0 && Character.isWhitespace(str.charAt(newStrLen - 1))) {
            newStrLen--;
        }
        return str.substring(0, newStrLen);
    } else {
        return str;
    }
}

