private void moveAllListNodes(DoublyLinkedList<E> list) {
	// Locate the head and tail of the `list`
	ListNode<E> head = list.head;
	ListNode<E> tail = list.tail;

	// Retrieve the next and previous nodes of the `head` and `tail`
	ListNode<E> headNext = head.next;
	ListNode<E> headPrev = head.prev;
	ListNode<E> tailNext = tail.next;
	ListNode<E> tailPrev = tail.prev;

	// Decrement the size of the `list`
	list.size--;

	// Update the links of the nodes
	headNext.prev = headPrev;
	headPrev.next = headNext;
	tailNext.prev = tailPrev;
	tailPrev.next = tailNext;

	// Update the links of this list
	this.head.prev = head;
	head.next = this.head;
	tail.prev = this.tail;
	this.tail.next = tail;

	// Update the size of this list
	this.size += list.size;

	// Clear the links of the `list`
	list.head = null;
	list.tail = null;
	list.size = 0;
}

