 * @param row the row number to select in the `table`
 * @param table the {@link JTable} to interact with
 * @param pane the {@link JScrollPane} to update
 */
public static void selectRow(int row, JTable table, JScrollPane pane) {
    // Select the specified row
    table.setRowSelectionInterval(row, row);

    // Scroll to the selected row
    Rectangle rect = table.getCellRect(row, 0, true);
    pane.getViewport().setViewPosition(rect.getLocation());

    // Ensure that the newly selected row is properly painted
    table.repaint();
    try {
        Thread.sleep(200);
    } catch (InterruptedException e) {
        e.printStackTrace();
    }
}

