private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the given vertices form a complete subgraph
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (!graph.containsEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }

    // Check if the subgraph is connected
    if (!connectComponents(graph, vertices)) {
        return false;
    }

    return true;
}

private static <V, E> boolean connectComponents(Graph<V, E> graph, Set<V> vertices) {
    // Find a connected component for the given vertices
    V startVertex = null;
    for (V vertex : vertices) {
        if (graph.getNeighbors(vertex).isEmpty()) {
            startVertex = vertex;
            break;
        }
    }
    if (startVertex == null) {
        return false;
    }

    // Breadth-first search to find all connected components
    Queue<V> queue = new LinkedList<>();
    Set<V> visited = new HashSet<>();
    queue.add(startVertex);
    visited.add(startVertex);
    while (!queue.isEmpty()) {
        V currentVertex = queue.remove();
        for (E edge : graph.getNeighbors(currentVertex)) {
            V neighbor = Graphs.getOppositeVertex(graph, edge, currentVertex);
            if (!visited.contains(neighbor)) {
                queue.add(neighbor);
                visited.add(neighbor);
            }
        }
    }

    // Check if all vertices are contained in a connected component
    for (V vertex : vertices) {
        if (!visited.contains(vertex)) {
            return false;
        }
    }

    return true;
}

