// This method checks whether the subgraph of <code>graph</code> induced by the given <code>vertices</code> is complete, i.e. a clique.

boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Build the subgraph induced by the given vertices
    Graph<V,E> subgraph = graph.subgraph(vertices);

    // Check if the subgraph is connected
    if (!subgraph.isConnected()) {
        return false;
    }

    // Check if the subgraph is a clique
    Set<V> neighbors = new HashSet<>();
    for (V vertex : vertices) {
        neighbors.addAll(graph.neighborsOf(vertex));
    }
    return neighbors.containsAll(vertices);
}

