private void pop(final String descriptor) {
    if (descriptor.charAt(0) == '(') {
      for (int i = 1; i < descriptor.length() - 1; i++) {
        outputFrame.pop(Type.getType(descriptor.substring(i + 1, i + 1)).getSize());
      }
    } else {
      outputFrame.pop(Type.getType(descriptor).getSize());
    }
  }

private void pop(String descriptor) {
    // Parse the descriptor to determine the number of abstract types to pop
    int count = 0;
    boolean isMethodDescriptor = false;
    for (int i = 0; i < descriptor.length(); i++) {
        char c = descriptor.charAt(i);
        if (c == 'L') {
            count++;
        } else if (c == '(') {
            isMethodDescriptor = true;
        }
    }

    if (isMethodDescriptor) {
        // Guard is not necessary here as it will always be true, but including it for clarity
        if (count > 0) {
            // The output frame stack should be resolved up to the specified frame
            outputFrame = outputFrame.resolved(count);
        }
    } else {
        // Pop the abstract types from the output frame stack
        for (int i = 0; i < count; i++) {
            outputFrame = outputFrame.popType();
        }
    }
}

private void pop (String descriptor) {
    int numTypes = Type.getType (descriptor).getParameterTypes ().length;
    for (int i = 0; i < numTypes; i++) {
        outputFrame.pop ();
    }
}

private void pop(String descriptor) {
    int paramCount = Type.getArgumentTypes(descriptor).length;
    for (int i = 0; i < paramCount; i++) {
        Class<?> type = PopFrame.stack.removeLast();
        if (type == null) {
            throw new NullPointerException("type is null");
        }
    }
}

private void pop(String descriptor) {
    int poppedTypesCount = Type.getArgumentTypes(descriptor).length;
    for (int i = 0; i < poppedTypesCount; i++) {
        outputFrame.pop();
    }
}

