public static String applyRelativePath(String path, String relativePath) {
    // Split the path into its constituent parts
    String[] pathParts = path.split("/");
    // Split the relative path into its constituent parts
    String[] relativePathParts = relativePath.split("/");
    // Create a new list to hold the resulting path parts
    List<String> newPathParts = new ArrayList<>();
    // Loop through the relative path parts
    for (String part : relativePathParts) {
        // If the part is the .. keyword, remove the last path part from the new path
        if (part.equals("..")) {
            if (!newPathParts.isEmpty()) {
                newPathParts.remove(newPathParts.size() - 1);
            }
        }
        // Otherwise, add the part to the new path
        else {
            newPathParts.add(part);
        }
    }
    // Join the path parts using "/" and return the resulting string
    return String.join("/", newPathParts);
}

public static String applyRelativePath(String path, String relativePath) {
    // Check if the relative path is absolute
    if (relativePath.startsWith("/")) {
        return relativePath;
    }

    // If the path is null, return an empty string
    if (path == null) {
        return "";
    }

    // Split the path into its components
    String[] pathComponents = path.split("/");

    // Split the relative path into its components
    String[] relativePathComponents = relativePath.split("/");

    // Create a list to store the new path components
    List<String> newPathComponents = new ArrayList<>();

    // Iterate over the components of the relative path
    for (String component : relativePathComponents) {
        // If the component is "..", remove the last path component from the new path
        if (component.equals("..")) {
            if (!pathComponents.isEmpty()) {
                newPathComponents.remove(newPathComponents.size() - 1);
            }
        }
        // Otherwise, add the component to the new path
        else {
            newPathComponents.add(component);
        }
    }

    // Join the new path components into a single string using "/" as the separator
    return String.join("/", newPathComponents);
}

