	int extensionIndex;
	if (lastSeparatorIndex == -1) {
		extensionIndex = -1;
	} else {
		int length = filename.length();
		do {
			extensionIndex = filename.indexOf(".", lastSeparatorIndex + 1);
			if (extensionIndex == -1) {
